const std = @import("std");

const Node = struct {
    value: i32,
    next: ?*Node,
};

pub fn main() !void {
    var n3 = Node{ .value = 30, .next = null };
    var n2 = Node{ .value = 20, .next = &n3 };
    var n1 = Node{ .value = 10, .next = &n2 };

    var current: ?*Node = &n1;
    while (current) |node| {
        std.debug.print("{} ", .{node.value});
        current = node.next;
    }
    std.debug.print("\n", .{});
}

